CREATE TABLE site_text ( key TEXT NOT NULL, lang TEXT NOT NULL REFERENCES languages(code), value TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')), PRIMARY KEY (key, lang) ); CREATE TABLE site_image ( key TEXT PRIMARY KEY, media_id INTEGER REFERENCES media(id) ON DELETE SET NULL, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) );
